use super::*;
use tempfile::TempDir;
use std::os::unix::fs::PermissionsExt;
fn at(days:i64)->String{time_ms(1_794_182_400_000+days*86_400_000).unwrap()}
fn fixture()->(TempDir,std::path::PathBuf){let dir=tempfile::tempdir().unwrap();fs::set_permissions(dir.path(),fs::Permissions::from_mode(0o700)).unwrap();let db=dir.path().join("events.sqlite");(dir,db)}
fn event(id:usize,now:&str)->LocalEvent{LocalEvent{id:format!("event-{id}"),source_id:"test".into(),entity_id:format!("entity-{id}"),event_type:LocalEventType::ExecutionFailed,occurred_at:None,observed_at:now.into(),result_code:"failed".into(),target:None}}
fn load(path:&Path,now:&str)->StoredState{serde_json::from_value(execute("events-load",path,json!({"now":now})).unwrap()).unwrap()}
fn commit(path:&Path,revision:u64,checkpoint:Checkpoint,events:Vec<LocalEvent>,now:&str)->CommitResult{let identity=load(path,now).identity;serde_json::from_value(execute("events-commit",path,json!({"identity":identity,"now":now,"revision":revision,"checkpoint":checkpoint,"events":events})).unwrap()).unwrap()}
fn page(path:&Path,now:&str,query:EventQuery)->EventPage{serde_json::from_value(execute("events-query",path,json!({"now":now,"query":query})).unwrap()).unwrap()}
#[test]fn events_transaction_revision_reopen_dedup_and_frozen_pagination(){
    let (_dir,path)=fixture();let now=at(0);assert_eq!(load(&path,&now).revision,0);
    let cp=Checkpoint{observed_at:Some(now.clone()),..Checkpoint::default()};
    let saved=commit(&path,0,cp.clone(),(0..100).map(|i|event(i,&now)).collect(),&now);assert_eq!(saved.added.len(),100);
    let first=page(&path,&now,EventQuery::default());assert_eq!(first.entries.len(),50);assert_eq!(first.upper,100);assert_eq!(first.next,Some(51));
    let second_commit=commit(&path,1,cp.clone(),vec![event(0,&now),event(100,&now)],&now);assert_eq!(second_commit.added.len(),1);assert_eq!(second_commit.retention.count,101);
    let second=page(&path,&now,EventQuery{upper:Some(first.upper),before:first.next,..EventQuery::default()});assert_eq!(second.entries.len(),50);assert_eq!(second.entries[0].id,"event-49");assert_eq!(second.entries[49].id,"event-0");assert!(second.next.is_none());
    assert_eq!(load(&path,&now).checkpoint,Some(cp.clone()));
    let stale=execute("events-commit",&path,json!({"identity":saved.identity,"now":now,"revision":0,"checkpoint":cp,"events":[event(101,&now)]})).unwrap_err();assert_eq!(stale.code,"OC_EVENT_STALE");assert_eq!(load(&path,&now).retention.count,101);
}
#[test]fn events_query_pruning_advances_revision_and_stale_checkpoint_cannot_commit(){let (_dir,path)=fixture();let now=at(0);commit(&path,0,Checkpoint::default(),vec![event(0,&now)],&now);let pruned=page(&path,&at(8),EventQuery::default());assert!(pruned.entries.is_empty());assert_eq!(pruned.revision,2);assert_eq!(pruned.retention.deleted_count,1);assert_eq!(pruned.retention.reason,Some(RetentionReason::Age));assert_eq!(pruned.upper,1);assert_eq!(load(&path,&at(8)).revision,2);}
#[test]fn events_batch_record_and_private_storage_boundaries_fail_before_commit(){let (_dir,path)=fixture();let now=at(0);let oversized:Vec<_>=(0..101).map(|i|event(i,&now)).collect();assert!(execute("events-commit",&path,json!({"identity":"not-created","now":now,"revision":0,"checkpoint":Checkpoint::default(),"events":oversized})).is_err());assert!(!path.exists());let mut large=event(0,&now);large.id="x".repeat(513);assert!(execute("events-commit",&path,json!({"identity":"not-created","now":now,"revision":0,"checkpoint":Checkpoint::default(),"events":[large]})).is_err());assert!(!path.exists());load(&path,&now);fs::set_permissions(&path,fs::Permissions::from_mode(0o644)).unwrap();assert_eq!(execute("events-load",&path,json!({"now":now})).unwrap_err().code,"OC_EVENT_PERMISSION");}
#[test]fn events_symlink_sidecar_wrong_schema_and_lock_are_visible(){
    let (dir,path)=fixture();let now=at(0);let real=dir.path().join("real");fs::write(&real,b"").unwrap();std::os::unix::fs::symlink(&real,&path).unwrap();assert!(execute("events-load",&path,json!({"now":now})).is_err());fs::remove_file(&path).unwrap();load(&path,&now);
    let side=dir.path().join("events.sqlite-wal");fs::write(&side,b"").unwrap();fs::set_permissions(&side,fs::Permissions::from_mode(0o600)).unwrap();assert_eq!(execute("events-load",&path,json!({"now":now})).unwrap_err().code,"OC_EVENT_SIDECAR");fs::remove_file(side).unwrap();
    let db=Connection::open(&path).unwrap();db.execute_batch("BEGIN EXCLUSIVE").unwrap();assert_eq!(execute("events-load",&path,json!({"now":now})).unwrap_err().code,"OC_EVENT_LOCKED");db.execute_batch("ROLLBACK;PRAGMA application_id=0").unwrap();db.close().unwrap();assert_eq!(execute("events-load",&path,json!({"now":now})).unwrap_err().code,"OC_EVENT_SCHEMA");
}
#[test]fn events_count_retention_is_bounded_without_duplicate_eviction(){let (_dir,path)=fixture();let now=at(0);let mut revision=0;for batch in 0..101{let saved=commit(&path,revision,Checkpoint::default(),(batch*100..batch*100+100).map(|i|event(i,&now)).collect(),&now);revision=saved.revision;assert!(saved.retention.count<=10_000);assert!(saved.retention.disk_bytes<=EVENT_DISK_BYTES);}let state=load(&path,&now);assert_eq!(state.retention.count,10_000);assert_eq!(state.retention.deleted_count,100);let repeat=commit(&path,revision,Checkpoint::default(),(100..200).map(|i|event(i,&now)).collect(),&now);assert!(repeat.added.is_empty());assert_eq!(repeat.retention.deleted_count,100);}
#[test]fn events_payload_retention_and_tombstones_prevent_replay(){let (_dir,path)=fixture();let now=at(0);let mut cp=Checkpoint{hermes:Some(HermesCursor{identity:"1:2".into(),baseline:0,high:3000,revisit:0,floor:0,since:now.clone(),last_observed_at:now.clone(),pending:vec![],pending_index:0}),..Checkpoint::default()};let prefix=&digest("1:2")[..16];let mut revision=0;let mut first=None;for batch in 0..25{let events=(batch*100+1..batch*100+101).map(|i|{let mut e=event(i,&now);e.id=format!("h:{prefix}:{i}:{}","a".repeat(32));e.target=Some(NavigationTarget::Schedule{id:"job".into(),identity:"x".repeat(1200)});if i==1{first=Some(e.clone());}e}).collect();let saved=commit(&path,revision,cp,events,&now);revision=saved.revision;cp=saved.checkpoint;}let before=load(&path,&now);assert_eq!(before.retention.reason,Some(RetentionReason::Bytes));assert!(before.retention.deleted_count>0);let saved=commit(&path,revision,cp,vec![first.unwrap()],&now);assert!(saved.added.is_empty());assert_eq!(saved.retention.count,before.retention.count);}
#[test]fn events_tombstone_capacity_moves_floor_and_records_gap(){let (_dir,path)=fixture();let now=at(0);let cp=Checkpoint{hermes:Some(HermesCursor{identity:"1:2".into(),baseline:0,high:50_000,revisit:0,floor:0,since:now.clone(),last_observed_at:now.clone(),pending:vec![],pending_index:0}),..Checkpoint::default()};commit(&path,0,cp.clone(),vec![],&now);let db=Connection::open(&path).unwrap();db.execute_batch("BEGIN").unwrap();let id=Sha256::digest(b"1:2")[..8].to_vec();for i in 1..=32769u64{db.execute("INSERT INTO event_tombstones VALUES(?,?,?,?)",params![Sha256::digest(i.to_le_bytes()).to_vec(),id,i,parse_ms(&now).unwrap()]).unwrap();}db.execute_batch("COMMIT").unwrap();db.close().unwrap();let old=at(-8);let saved=commit(&path,1,cp,vec![event(999,&old)],&now);let cursor=saved.checkpoint.hermes.unwrap();assert!(cursor.floor>0);assert!(saved.checkpoint.coverage.iter().any(|c|c.code.as_deref()==Some("hermes-dedup-capacity-gap")));}
fn hermes_fixture()->(TempDir,std::path::PathBuf){let dir=tempfile::tempdir().unwrap();let path=dir.path().join("hermes.sqlite");let db=Connection::open(&path).unwrap();db.execute_batch("CREATE TABLE executions(id TEXT,job_id TEXT,status TEXT,claimed_at TEXT,finished_at TEXT,delivery_outcome TEXT,prompt TEXT,output TEXT)").unwrap();db.close().unwrap();(dir,path)}
fn insert(path:&Path,id:&str,status:&str,claimed:&str,finished:Option<&str>,delivery:Option<&str>){let db=Connection::open(path).unwrap();db.execute("INSERT INTO executions VALUES(?,?,?,?,?,?,?,?)",params![id,"job",status,claimed,finished,delivery,"PRIVATE_PROMPT", "PRIVATE_OUTPUT"]).unwrap();db.close().unwrap();}
fn read_hermes_event(path:&Path,cursor:Option<HermesCursor>,now:&str)->HermesRead{serde_json::from_value(execute("hermes-events",path,json!({"cursor":cursor,"now":now})).unwrap()).unwrap()}
#[test]fn hermes_baseline_pending_late_updates_and_rowid_ingestion(){let (_dir,path)=hermes_fixture();let now=at(0);insert(&path,"historic","failed",&now,Some(&now),Some("failed"));insert(&path,"pending","running",&now,None,None);let baseline=read_hermes_event(&path,None,&now);assert_eq!(baseline.coverage.state,CoverageState::Baseline);assert!(baseline.rows.is_empty());assert_eq!(baseline.cursor.pending.len(),1);let db=Connection::open(&path).unwrap();db.execute("UPDATE executions SET status='failed',finished_at=?,delivery_outcome='failed' WHERE id='pending'",[&now]).unwrap();db.close().unwrap();insert(&path,"late","failed",&now,Some(&now),Some("failed"));let next=read_hermes_event(&path,Some(baseline.cursor),&now);assert_eq!(next.rows.len(),2);assert!(next.cursor.pending.is_empty());let events=crate::events::collector::execution_events(&next,&[],&now).unwrap();assert_eq!(events.len(),4);let json=serde_json::to_string(&next).unwrap();assert!(!json.contains("PRIVATE_"));let revisited=read_hermes_event(&path,Some(next.cursor),&now);assert!(revisited.rows.iter().any(|r|r.id=="late"));}
#[test]fn hermes_nanoseconds_offsets_invalid_status_and_pending_limit(){let (_dir,path)=hermes_fixture();let now="2026-11-09T00:00:00.001Z";insert(&path,"one","running","2026-11-08T19:00:00.000000002-05:00",None,None);let baseline=read_hermes_event(&path,None,now);assert_eq!(baseline.cursor.pending.len(),1);let db=Connection::open(&path).unwrap();db.execute("UPDATE executions SET finished_at='2026-11-09T00:00:00.000000001Z'",[]).unwrap();db.close().unwrap();assert!(execute("hermes-events",&path,json!({"cursor":baseline.cursor,"now":now})).is_err());let db=Connection::open(&path).unwrap();db.execute_batch("DELETE FROM executions").unwrap();db.close().unwrap();insert(&path,"unknown","mystery",now,None,None);assert!(execute("hermes-events",&path,json!({"cursor":null,"now":now})).is_err());let db=Connection::open(&path).unwrap();db.execute_batch("DELETE FROM executions").unwrap();for i in 0..129{db.execute("INSERT INTO executions(id,job_id,status,claimed_at) VALUES(?, 'job','running',?)",params![format!("p{i}"),now]).unwrap();}db.close().unwrap();assert!(execute("hermes-events",&path,json!({"cursor":null,"now":now})).is_err());}
#[test]fn hermes_replacement_and_missing_pending_report_coverage_gaps(){let (dir,path)=hermes_fixture();let now=at(0);insert(&path,"pending","running",&now,None,None);let baseline=read_hermes_event(&path,None,&now);let db=Connection::open(&path).unwrap();db.execute_batch("DELETE FROM executions;INSERT INTO executions(id,job_id,status,claimed_at,delivery_outcome) VALUES('new','job','completed','2026-11-09T00:00:00.000Z','delivered')").unwrap();db.close().unwrap();let future="2026-11-10T00:00:00.000Z";assert!(execute("hermes-events",&path,json!({"cursor":baseline.cursor,"now":future})).is_err());let old=dir.path().join("old.sqlite");fs::rename(&path,&old).unwrap();let db=Connection::open(&path).unwrap();db.execute_batch("CREATE TABLE executions(id TEXT,job_id TEXT,status TEXT,claimed_at TEXT,finished_at TEXT,delivery_outcome TEXT)").unwrap();db.close().unwrap();let next=read_hermes_event(&path,Some(baseline.cursor),future);assert_eq!(next.coverage.code.as_deref(),Some("hermes-history-reset"));assert!(next.rows.is_empty());}
#[test]fn notification_journal_claim_survives_reopen_and_bad_file_is_not_overwritten(){let (dir,_)=fixture();let path=dir.path().join("notifications.json");assert_eq!(execute("events-journal-read",&path,json!({})).unwrap(),json!(crate::events::journal::Journal::default()));let mut journal=crate::events::journal::Journal::default();journal.identity=Some("database:1".into());journal.cursor.sequence=88;journal.cursor.unconfirmed=true;execute("events-journal-write",&path,json!(journal)).unwrap();assert_eq!(execute("events-journal-read",&path,json!({})).unwrap(),json!(journal));assert_eq!(fs::metadata(&path).unwrap().mode()&0o777,0o600);fs::write(&path,b"broken").unwrap();assert!(execute("events-journal-read",&path,json!({})).is_err());assert_eq!(fs::read(&path).unwrap(),b"broken");fs::set_permissions(&path,fs::Permissions::from_mode(0o644)).unwrap();assert!(execute("events-journal-write",&path,json!(journal)).is_err());}

#[test]fn events_byte_limits_reject_large_payload_and_oversized_database(){
    let (_dir,path)=fixture();let now=at(0);let mut oversized=event(0,&now);oversized.id="a".repeat(512);oversized.entity_id="b".repeat(256);oversized.target=Some(NavigationTarget::Schedule{id:"job".into(),identity:"c".repeat(1536)});
    assert!(execute("events-commit",&path,json!({"identity":"not-created","now":now,"revision":0,"checkpoint":Checkpoint::default(),"events":[oversized]})).is_err());assert!(!path.exists());
    load(&path,&now);let file=OpenOptions::new().write(true).open(&path).unwrap();file.set_len(MAIN_BYTES+1).unwrap();close_file(file).unwrap();assert_eq!(execute("events-load",&path,json!({"now":now})).unwrap_err().code,"OC_COLLECTION_LIMIT");
}
#[test]fn events_invalid_stored_payload_is_not_materialized_or_silently_skipped(){
    let (_dir,path)=fixture();let now=at(0);commit(&path,0,Checkpoint::default(),vec![event(1,&now)],&now);let db=Connection::open(&path).unwrap();db.execute("UPDATE events SET payload=?",["private".repeat(20_000)]).unwrap();db.close().unwrap();assert!(execute("events-query",&path,json!({"now":now,"query":{}})).is_err());
}
#[test]fn hermes_deleted_pending_row_reports_gap_without_resetting_other_cursor(){
    let (_dir,path)=hermes_fixture();let now=at(0);insert(&path,"pending","running",&now,None,None);insert(&path,"completed","completed",&now,Some(&now),Some("delivered"));let baseline=read_hermes_event(&path,None,&now);let db=Connection::open(&path).unwrap();db.execute("DELETE FROM executions WHERE id='pending'",[]).unwrap();db.close().unwrap();let next=read_hermes_event(&path,Some(baseline.cursor),&now);assert_eq!(next.coverage.code.as_deref(),Some("hermes-pending-gap"));assert_eq!(next.cursor.high,2);assert!(next.cursor.pending.is_empty());assert!(next.rows.is_empty());
}
#[test]fn hermes_incremental_backlog_is_bounded_and_late_timestamp_rows_are_not_lost(){
    let (_dir,path)=hermes_fixture();let now=at(0);let baseline=read_hermes_event(&path,None,&now);let db=Connection::open(&path).unwrap();for i in 0..20{db.execute("INSERT INTO executions(id,job_id,status,claimed_at,finished_at,delivery_outcome) VALUES(?, 'job','failed',?,?,'failed')",params![format!("e{i}"),now,now]).unwrap();}db.close().unwrap();let first=read_hermes_event(&path,Some(baseline.cursor),&now);assert_eq!(first.cursor.high,16);assert_eq!(first.rows.len(),16);assert_eq!(first.coverage.state,CoverageState::CatchingUp);let second=read_hermes_event(&path,Some(first.cursor),&now);assert_eq!(second.cursor.high,20);assert!(second.rows.len()<=40);assert!(second.rows.iter().any(|r|r.id=="e19"));
}
#[test]fn notification_journal_recovers_one_crash_temporary_and_serializes_writers(){
    use std::os::fd::AsRawFd;
    let (dir,_)=fixture();let path=dir.path().join("notifications.json");let temp=dir.path().join(".notifications.json.claim.tmp");fs::write(&temp,b"partial claim from terminated worker").unwrap();fs::set_permissions(&temp,fs::Permissions::from_mode(0o600)).unwrap();let journal=crate::events::journal::Journal::default();execute("events-journal-write",&path,json!(journal)).unwrap();assert!(!temp.exists());
    let lock_path=dir.path().join(".notifications.json.lock");let lock=OpenOptions::new().read(true).write(true).open(lock_path).unwrap();assert_eq!(unsafe{libc::flock(lock.as_raw_fd(),libc::LOCK_EX|libc::LOCK_NB)},0);assert_eq!(execute("events-journal-write",&path,json!(journal)).unwrap_err().code,"OC_NOTIFICATION_JOURNAL_BUSY");close_file(lock).unwrap();assert_eq!(execute("events-journal-read",&path,json!({})).unwrap(),json!(journal));
}

#[test]fn events_commit_rejects_replaced_database_even_when_revision_matches(){
    let (dir,path)=fixture();let now=at(0);let loaded=load(&path,&now);fs::rename(&path,dir.path().join("old.sqlite")).unwrap();let replacement=load(&path,&now);assert_eq!(loaded.revision,replacement.revision);assert_ne!(loaded.identity,replacement.identity);
    let error=execute("events-commit",&path,json!({"identity":loaded.identity,"revision":loaded.revision,"now":now,"checkpoint":Checkpoint::default(),"events":[event(1,&now)]})).unwrap_err();assert_eq!(error.code,"OC_COLLECTION_CHANGED");assert_eq!(load(&path,&now).retention.count,0);
}
